UPDATE public.personas
SET description = 'الملكة سبك نفرو (سوبك نفرو / نفر سوبك)، أول امرأة مؤكدة تاريخياً حكمت مصر القديمة بصفتها فرعونة، وآخر حكام الأسرة الثانية عشرة ونهاية عصر الدولة الوسطى (نحو 1806–1802 ق.م). دام حكمها وفقاً لبردية تورين ثلاث سنوات وعشرة أشهر وأربعة وعشرين يوماً. تبنّت الألقاب الملكية الكاملة مع تعديلات تعكس أنوثتها مثل «ابنة رع» و«حورس الأنثى»، وكانت أول حاكم يربط اسمه بالإله التمساح سوبك فى اسم النِسبة (نومن) واسم العرش (برينومن).'
WHERE id = '1ba683bd-fcd2-4711-8f59-a6e5afb08fb5';